with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as CLASSIFICATION_TYPE
        , BUSS_TYPE as CLASSIFICATION_VALUE
        , 'BA_HCP_DT_PREMIUM' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_dt_premium') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POL_SERIAL_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as CLASSIFICATION_TYPE
        , PD_BUSINESS_TYPE as CLASSIFICATION_VALUE
        , 'BA_HCP_PROD_8428_GPG_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8428_gpg_loader') }}
    where (nullif(trim(POL_SERIAL_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POL_SERIAL_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as CLASSIFICATION_TYPE
        , PD_BUSINESS_TYPE as CLASSIFICATION_VALUE
        , 'BA_HCP_PROD_8432_ECP_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8432_ecp_loader') }}
    where (nullif(trim(POL_SERIAL_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POL_SERIAL_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as CLASSIFICATION_TYPE
        , PD_BUSINESS_TYPE as CLASSIFICATION_VALUE
        , 'BA_HCP_PROD_8433_FHC_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8433_fhc_loader') }}
    where (nullif(trim(POL_SERIAL_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POL_SERIAL_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as CLASSIFICATION_TYPE
        , PD_BUSINESS_TYPE as CLASSIFICATION_VALUE
        , 'BA_HCP_PROD_8439_CLH_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8439_clh_loader') }}
    where (nullif(trim(POL_SERIAL_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as CLASSIFICATION_TYPE
        , GRADE_BUCKET as CLASSIFICATION_VALUE
        , 'BGIL_GMC_FINAL_INSTL_DATA' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_bgil_gmc_final_instl_data') }}
    where (nullif(trim(POLICY_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_REF))) as HUB_POLICY_HK
        , cast(null as varchar) as CLASSIFICATION_TYPE
        , BUSINESS_TYPE as CLASSIFICATION_VALUE
        , 'BJAZ_BANDHAN_MEDI_CLAM' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_bandhan_medi_clam') }}
    where (nullif(trim(POLICY_REF),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__REFERENCE_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as CLASSIFICATION_TYPE
        , BUSINESS_TYPE as CLASSIFICATION_VALUE
        , 'BJAZ_GPG_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_gpg_pol_dtls') }}
    where (nullif(trim(REFERENCE_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as CLASSIFICATION_TYPE
        , BUSINESS_TYPE as CLASSIFICATION_VALUE
        , 'BJAZ_GRP_HLT_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_dtls') }}
    where (nullif(trim(POLICY_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_REF))) as HUB_POLICY_HK
        , cast(null as varchar) as CLASSIFICATION_TYPE
        , BUSINESS_TYPE as CLASSIFICATION_VALUE
        , 'BJAZ_HEALTH_WEBSERVICE_INFO' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_health_webservice_info') }}
    where (nullif(trim(POLICY_REF),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as CLASSIFICATION_TYPE
        , ENROLLMENT_TYPE as CLASSIFICATION_VALUE
        , 'BJAZ_ENROLL_SCR_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_scr_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as CLASSIFICATION_TYPE
        , PARAM_VALUE as CLASSIFICATION_VALUE
        , 'BJAZ_CTNGY_NR_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_nr_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , 'BUSINESS_TYPE' as CLASSIFICATION_TYPE
        , BUSS_TYPE as CLASSIFICATION_VALUE
        , 'BJAZ_STARPKG_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_starpkg_pol_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , 'BUSINESS_SOURCE' as CLASSIFICATION_TYPE
        , BUSINESS_SOURCE as CLASSIFICATION_VALUE
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        CLASSIFICATION_TYPE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then CLASSIFICATION_VALUE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLASSIFICATION_VALUE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then CLASSIFICATION_VALUE end)) as CLASSIFICATION_VALUE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK, CLASSIFICATION_TYPE
),

hashed as (
    select
        *,
        case when CLASSIFICATION_TYPE is not null or CLASSIFICATION_VALUE is not null
                     then md5(upper(coalesce(cast(CLASSIFICATION_TYPE as varchar), '') || '|' || coalesce(cast(CLASSIFICATION_VALUE as varchar), '')))
                end as SAT_POLICY_CLASSIFICATION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_CLASSIFICATION_HASHDIFF is not null
